def transform(grid):
    out = [row[:] for row in grid]
    rows = list(range(1, len(grid), 2))
    cols = [1, 4, 7, 10, 13]
    bg = grid[0][0]

    # Preserve each row's number of marked blocks while arranging the marks
    # into a descending column profile, choosing the arrangement closest
    # to the input.
    patterns = []
    for r in rows:
        k = sum(grid[r][c] == 0 for c in cols)
        patterns.append([
            tuple(i in comb for i in range(5))
            for comb in __import__("itertools").combinations(range(5), k)
        ])

    target = [4, 3, 2, 2, 1]
    states = {(0, 0, 0, 0, 0): (0, [])}
    for r, choices in zip(rows, patterns):
        nxt = {}
        for sums, (score, chosen) in states.items():
            for p in choices:
                ns = tuple(sums[j] + int(p[j]) for j in range(5))
                if any(ns[j] > target[j] for j in range(5)):
                    continue
                val = score + sum(
                    int(p[j]) == int(grid[r][cols[j]] == 0)
                    for j in range(5)
                )
                if ns not in nxt or val > nxt[ns][0]:
                    nxt[ns] = (val, chosen + [p])
        states = nxt

    selected = states.get(tuple(target), (0, [])[1])
    if selected:
        for r, p in zip(rows, selected):
            for j, c in enumerate(cols):
                out[r][c] = 0 if p[j] else bg
    return out
