def transform(grid):
    from functools import lru_cache
    from itertools import combinations

    out = [row[:] for row in grid]
    rows = list(range(1, len(grid), 2))
    cols = [1, 4, 7, 10, 13]
    bg = grid[0][0]
    ncols = len(cols)

    original = []
    for r in rows:
        original.append(tuple(int(grid[r][c] == 0) for c in cols))

    total = sum(sum(row) for row in original)
    # The five column counts form a descending staircase.
    first = (total + ncols * (ncols - 1) // 2) // ncols
    targets = tuple(first - j for j in range(ncols))

    options = []
    for bits in original:
        count = sum(bits)
        options.append([
            tuple(int(j in chosen) for j in range(ncols))
            for chosen in combinations(range(ncols), count)
        ])

    @lru_cache(None)
    def solve(i, remaining):
        if i == len(rows):
            return (0, ()) if all(x == 0 for x in remaining) else (10**9, ())
        best_cost, best_choice = 10**9, ()
        for pattern in options[i]:
            rem = tuple(remaining[j] - pattern[j] for j in range(ncols))
            if min(rem) < 0 or any(x > len(rows) - i - 1 for x in rem):
                continue
            cost, suffix = solve(i + 1, rem)
            cost += sum(pattern[j] != original[i][j] for j in range(ncols))
            if cost < best_cost:
                best_cost, best_choice = cost, (pattern,) + suffix
        return best_cost, best_choice

    _, chosen = solve(0, targets)
    if len(chosen) == len(rows):
        for r, pattern in zip(rows, chosen):
            for c, bit in zip(cols, pattern):
                out[r][c] = 0 if bit else bg
    return out
